def largest_clear_set(n, conflicts):
    """Strategies 0 to n - 1; a pair in conflicts
    cannot run together. Return the size of the
    largest set with no conflicting pair."""
    clash = [0] * n          # clash[i]: mask of i's conflicts
    for a, b in conflicts:
        clash[a] |= 1 << b
        clash[b] |= 1 << a
    best = 0
    for mask in range(1 << n):
        ok = True
        for i in range(n):
            if mask >> i & 1 and clash[i] & mask:
                ok = False
                break
        if ok:
            best = max(best, bin(mask).count("1"))
    return best

