def check_book(n, out):
    if n == 1:
        return out is None
    if not isinstance(out, list) or len(out) != n:
        return False
    if any(type(x) is not int for x in out):
        return False
    if len(set(out)) != n:
        return False
    if any(x == 0 or abs(x) > n for x in out):
        return False
    return sum(out) == 0
